<script lang="ts">import PageShell from '$lib/components/PageShell.svelte';import {page} from '$app/state';import {listings,invoices} from '$lib/api';import {session} from '$lib/stores/session';let item=$state<any>(null),error=$state(''),status=$state('');$effect(()=>{listings.one(page.params.id||'').then(v=>item=v).catch(e=>error=e.message)});async function verify(){try{const v=await invoices.verify(item.bolt11);status=v.settled?'Paid':'Awaiting settlement'}catch(e){error=e instanceof Error?e.message:'Unable to verify payment.'}}</script>
<PageShell eyebrow="LISTING DETAIL" title={item?.title||'Loading listing…'}>{#if error}<p class="alert">{error}</p>{:else if item}<div class="detail-grid"><div class="detail-art">♻</div><div class="form-card"><p class="muted">{item.producerName}</p><p>{item.description}</p><h2>{Number(item.priceSats).toLocaleString()} sats</h2>{#if $session?.role==='farmer' && item.bolt11}<p class="state">Pay the Producer invoice to reserve this item.</p><img src={`https://quickchart.io/qr?text=${encodeURIComponent(item.bolt11)}&size=220`} alt="Lightning invoice QR code"/><a class="btn primary" href={`lightning:${item.bolt11}`}>Open in Blink Wallet</a><button class="btn ghost" onclick={verify}>Verify payment</button><p class="success">{status}</p>{/if}</div></div>{/if}</PageShell>
